const express = require('express');
const { Worker } = require('worker_threads');
const path = require('path');
const { authenticate } = require('../middleware/jwt');
const Recording = require('../models/Recording');

const router = express.Router();

router.post('/api/telephony/recordings/:recordingId/transcribe', authenticate, async (req, res) => {
  const recording = await Recording.findOne({
    _id: req.params.recordingId,
    userId: req.user.id
  });
  if (!recording) {
    return res.status(403).json({ error: 'Unauthorized: call recording not found or does not belong to you' });
  }

  const worker = new Worker(path.resolve(__dirname, '../workers/speechTranscriber.js'), {
    workerData: { recordingId: req.params.recordingId }
  });

  worker.on('message', (data) => {
    res.json({ recordingId: req.params.recordingId, transcription: data.transcriptText });
  });

  worker.on('error', () => {
    res.status(500).json({ error: 'Transcription worker error' });
  });
});
